import spidev
import time
import signal

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi_opened = False

    def open_spi(self):
        try:
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
            self.spi_opened = True
        except OSError as e:
            print(f"Failed to open SPI device: {e}")
            self.spi_opened = False
        except IOError as e:
            print(f"Failed to open SPI device: {e}")
            self.spi_opened = False

    def send_spi_command(self, data):
        if not self.spi_opened:
            return None
        try:
            return self.spi.xfer2(data)
        except OSError as e:
            print(f"SPI transfer failed: {e}")
            return None
        except IOError as e:
            print(f"SPI transfer failed: {e}")
            return None

    def extract_10bit(self, response):
        if response is None or len(response) < 3:
            return None
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        response = self.send_spi_command([0x01, 0x80, 0x00])
        return self.extract_10bit(response)

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None
        return float(raw_data) * (5.0 / 1023.0)

    def close(self):
        if self.spi_opened:
            self.spi.close()
            self.spi_opened = False

    def run(self):
        self.open_spi()
        if not self.spi_opened:
            print("Failed to open SPI device. Exiting...")
            return

        try:
            while True:
                raw_data = self.read_raw_data()
                weight = self.convert_to_weight(raw_data)
                if weight is not None:
                    print(f"Weight: {weight:.2f} kg")
                time.sleep(0.5)
        except KeyboardInterrupt:
            print("\nShutting down due to KeyboardInterrupt...")
        finally:
            self.close()
            print("SPI device closed.")

def main():
    signal.signal(signal.SIGTERM, lambda signum, frame: sys.exit())
    reader = LoadCellReader()
    reader.run()

if __name__ == "__main__":
    main()

