    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise Exception('Failed to connect to pigpio daemon')
        self.dir = Device(dir_pin)
        self.step = PWMOutputDevice(step_pin, frequency=500)
        self.ms0 = Device(ms0_pin)
        self.ms1 = Device(ms1_pin)
        self.set_microstep_resolution('Full')
        self.set_direction('CCW')

    def set_microstep_resolution(self, resolution):
        resolutions = {
            'Full': (0, 0),
            'Half': (0, 1),
            'Quarter': (1, 0),
            'Eighth': (1, 1)
        }
        if resolution not in resolutions:
            raise ValueError('Invalid microstep resolution')
        self.ms0.value, self.ms1.value = resolutions[resolution]

    def set_direction(self, direction):
        directions = {
            'CW': 0,
            'CCW': 1
        }
        if direction not in directions:
            raise ValueError('Invalid direction')
        self.dir.value = directions[direction]

    def set_pwm_duty_cycle(self, duty_cycle):
        if not 0 <= duty_cycle <= 255:
            raise ValueError('Duty cycle must be between 0 and 255')
        self.step.value = duty_cycle / 255

class SensorManager:
    def __init__(self):
        try:
            self.i2c = adafruit_lsm303.LSM303(adafruit_lsm303.LSM303_I2C())
            self.accel = LSM303_ACCEL(self.i2c)
            self.mag = LSM303_MAG(self.i2c)
        except Exception as e:
            raise Exception('Failed to initialize sensors: {}'.format(e))

    def read_acceleration(self):
        return self.accel.acceleration

    def read_magnetic_field(self):
        return self.mag.magnetic

    def read_heading(self):
        return self.mag.heading

    def read_inclination(self):
        return self.mag.pitch, self.mag.roll

class ADCManager:
    def __init__(self, address=0x48, gain=1):
        self.adc = adafruit_ads1015.ADS1015(address=address)
        self.adc.gain = gain
        self.channel0 = AnalogIn(self.adc, adafruit_ads1015.P0_1)

    def read_voltage(self):
        return self.channel0.voltage

def exit_handler(signal, frame):
    motor.pi.stop()
    exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, exit_handler)
    signal.signal(signal.SIGTERM, exit_handler)

    motor = MotorController(dir_pin=20, step_pin=21, ms0_pin=14, ms1_pin=15)
    sensor = SensorManager()
    adc = ADCManager()

    while True:
        try:
            duty_cycle = int(adc.read_voltage() / 3.3 * 255)
            motor.set_pwm_duty_cycle(duty_cycle)

            print('Acceleration: ', sensor.read_acceleration())
            print('Magnetic Field: ', sensor.read_magnetic_field())
            print('Heading: ', sensor.read_heading())
            print('Inclination: ', sensor.read_inclination())

            time.sleep(1)
        except Exception as e:
            print('Error: ', e)
            exit(1)

