import time
from smbus2 import SMBus, i2c_msg

MAX_BATTERY_VOLTAGE = 13.8
MIN_BATTERY_VOLTAGE = 10.5
R1 = 2000
R2 = 1000
I2C_BUS = 1
I2C_ADDR = 0x48
PGA = 0b010
MUX = 0b100

class ADS1115:
    def __init__(self, i2c_bus, i2c_addr, pga, mux):
        self.i2c_bus = i2c_bus
        self.i2c_addr = i2c_addr
        self.pga = pga
        self.mux = mux
        self.config = (pga << 9) | (mux << 4) | 0b10000000

    def read_volts(self):
        try:
            with SMBus(self.i2c_bus) as bus:
                bus.write_byte_data(self.i2c_addr, 0x01, self.config)
                time.sleep(0.01)
                raw = bus.read_word_data(self.i2c_addr, 0x00)
                if raw & 0x8000:
                    raw -= 65536
                volts = (raw * (3600 / (R1 + R2))) / 32768
                return volts
        except Exception as e:
            print(f"Error reading from ADS1115: {e}")
            return None

def main():
    adc = ADS1115(I2C_BUS, I2C_ADDR, PGA, MUX)
    last_percent = None
    while True:
        try:
            volts = adc.read_volts()
            if volts is not None:
                percent = (volts - MIN_BATTERY_VOLTAGE) / (MAX_BATTERY_VOLTAGE - MIN_BATTERY_VOLTAGE) * 100
                percent = max(0, min(100, percent))
                if last_percent is None or abs(percent - last_percent) > 1:
                    print(f"Battery voltage: {volts:.2f}V ({percent:.2f}%)")
                    last_percent = percent
        except Exception as e:
            print(f"Error in main loop: {e}")
        time.sleep(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nExiting gracefully...")

import smbus2
import time
import signal
import sys

class ADS1115:
    def __init__(self, bus, addr):
        self.bus = bus
        self.addr = addr
        self.configure(0x8583)  # PGA gain=1, 128sps, single-ended, single-shot

    def configure(self, config):
        self.bus.write_word_data(self.addr, 0x01, config)

    def read(self, channel):
        start = time.time()
        while (self.bus.read_word_data(self.addr, 0x01) & 0x8000):
            if (time.time() - start) > 0.1:
                raise TimeoutError("ADC conversion timeout")
        return self.bus.read_word_data(self.addr, channel)

def main():
    try:
        bus = smbus2.SMBus(1)
    except Exception as e:
        print(f"I2C initialization error: {e}")
        sys.exit(1)

    adc = ADS1115(bus, 0x48)

    def exit_gracefully(signum, frame):
        bus.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, exit_gracefully)

    while True:
        try:
            print(f"AIN0: {adc.read(0)}, AIN1: {adc.read(1)}, AIN2: {adc.read(2)}, AIN3: {adc.read(3)}")
        except Exception as e:
            print(f"I2C or timeout error: {e}")
        time.sleep(0.05)

if __name__ == "__main__":
    main()

