import csv
import logging
import signal
import time
from datetime import datetime

import numpy as np
import spidev

class SoilMoistureSensor:
    def __init__(self, spi_bus=0, spi_device=0, dry=820, wet=400):
        self.spi = spidev.SpiDev()
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.dry = dry
        self.wet = wet
        self.history = []
        self.log_file = open('soil_moisture_log.csv', 'a', newline='')
        self.log_writer = csv.writer(self.log_file)

    def open_spi(self):
        try:
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = 1200000
        except (IOError, OSError) as e:
            logging.error(f"Failed to open SPI device: {e}")
            exit(1)

    def close_spi(self):
        self.spi.close()

    def read_raw(self, channel=2):
        cmd = 0x1000 | (channel << 8)
        frame = [(cmd >> i) & 0xff for i in range(16, -1, -8)]
        response = self.spi.xfer2(frame)
        return ((response[2] & 0x03) << 8) | response[1]

    def calibrate(self, raw):
        return 100 * (self.wet - raw) / (self.wet - self.dry)

    def log_reading(self, moisture):
        timestamp = datetime.now().isoformat()
        self.log_writer.writerow([timestamp, moisture])
        self.log_file.flush()

    def compute_stats(self):
        if len(self.history) > 0:
            return np.mean(self.history), np.std(self.history)
        else:
            return None, None

    def main_loop(self, interval=1, samples=25):
        try:
            for _ in range(samples):
                raw = self.read_raw()
                if raw == 0 or raw == 1023:
                    logging.warning("Sensor not connected or saturated")
                    continue
                moisture = self.calibrate(raw)
                self.history.append(moisture)
                self.log_reading(moisture)
                time.sleep(interval)
        except KeyboardInterrupt:
            logging.info("Interrupt received, exiting")
        finally:
            self.close_spi()
            self.log_file.close()

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, exiting")
        self.close_spi()
        self.log_file.close()
        exit(0)

if __name__ == "__main__":
    sensor = SoilMoistureSensor()
    sensor.open_spi()
    signal.signal(signal.SIGINT, sensor.signal_handler)
    signal.signal(signal.SIGTERM, sensor.signal_handler)
    sensor.main_loop()

import RPi.GPIO as GPIO
import spidev
import time
import queue
import logging
import threading
import argparse

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.stop_event = threading.Event()

        if self.sensor_type == 'digital':
            self.gpio_pins = gpio_pins
            GPIO.setup(self.gpio_pins, GPIO.IN)
        elif self.sensor_type == 'analog':
            self.spi = spidev.SpiDev()
            try:
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
            except Exception as e:
                logging.error(f"Failed to open SPI device: {e}")
                raise

    def read_digital(self):
        return GPIO.input(self.gpio_pins)

    def read_analog(self, channel):
        cmd = 0x80 | (0x10 * (channel & 0x07))
        reply = self.spi.xfer2([cmd, 0])
        data = ((reply[0] & 0x01) << 9) | reply[1]
        return data

    def run(self):
        last_event = time.time()
        while not self.stop_event.is_set():
            if self.sensor_type == 'digital':
                value = self.read_digital()
            elif self.sensor_type == 'analog':
                value = min(self.read_analog(channel) for channel in self.channels)
            if value >= self.threshold and time.time() - last_event >= 0.1:
                last_event = time.time()
                if self.log_queue is not None:
                    self.log_queue.put((self.sensor_id, value))
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.stop_event.set()
        if self.sensor_type == 'digital':
            GPIO.cleanup(self.gpio_pins)
        elif self.sensor_type == 'analog':
            self.spi.close()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--sensor_type', choices=['digital', 'analog'], required=True)
    parser.add_argument('--threshold', type=int, required=True)
    parser.add_argument('--sample_rate', type=float, required=True)
    parser.add_argument('--log_file', required=True)
    parser.add_argument('--gpio_pins', type=int, nargs='+', default=[])
