class ADS1115_I2C:
    def __init__(self, i2c_addr=0x48):
        self.i2c_addr = i2c_addr
        self.bus = smbus2.SMBus(1)
        self.adc = ADS1115(self.bus, self.i2c_addr)

    def read(self, channel, pga):
        valid_pgas = [6144, 4096, 2048, 1024, 512, 256]
        if pga not in valid_pgas:
            raise ValueError(f"Invalid PGA value. Choose from {valid_pgas}")
        if not 0 <= channel <= 3:
            raise ValueError("Channel must be between 0 and 3")
        try:
            self.adc.pga = pga
            self.adc.mode = ADS1115.SINGLE
            self.adc.channel = channel
            time.sleep(0.01)  # wait 10ms for conversion to complete
            raw_reading = self.adc.read_conversion()
            return raw_reading * pga / 32768.0
        except Exception as e:
            print(f"Error reading from ADS1115: {e}")
            return None

    def __del__(self):
        self.bus.close()

