    def __init__(self):
        self.spi = None
        self.actuator = None
        self.log_file = os.path.expanduser('~/logs/industrial_air_quality.log')
        self.config = self.load_config()

    def load_config(self):
        try:
            with open('config.json', 'r') as f:
                config = json.load(f)
                return config
        except FileNotFoundError:
            print('config.json not found.')
            exit(1)
        except json.JSONDecodeError:
            print('config.json is not a valid JSON file.')
            exit(1)
        except IOError:
            print('Error reading config.json.')
            exit(1)

    def setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 1000000
            return self.spi
        except spidev.SpiDevError:
            print('Error opening SPI device.')
            exit(1)

    def setup_actuator(self):
        try:
            self.actuator = OutputDevice(self.config['actuator_pin'], active_high=True)
            return self.actuator
        except Exception as e:
            print(f'Error setting up actuator: {e}')
            exit(1)

    def read_adc(self, channel):
        try:
            r = self.spi.xfer2([1, (8 | channel) << 4, 0])
            adc_count = ((r[1] & 3) << 8) | r[2]
            adc_volts = adc_count * 3.3 / 1023
            return adc_volts
        except Exception as e:
            print(f'Error reading ADC: {e}')
            exit(1)

    def check_thresholds(self, sensor, voltage):
        warning = self.config[f'{sensor}_warning']
        critical = self.config[f'{sensor}_critical']
        if voltage >= critical:
            self.actuator.on()
            print(f'{sensor.upper()} CRITICAL: {voltage:.3f}V')
        elif voltage >= warning:
            print(f'{sensor.upper()} WARNING: {voltage:.3f}V')
        else:
            self.actuator.off()

    def log_reading(self, mq2_volts, mq7_volts, mq135_volts):
        try:
            os.makedirs(os.path.dirname(self.log_file), exist_ok=True)
            with open(self.log_file, 'a') as f:
                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                f.write(f'{timestamp},{mq2_volts:.3f},{mq7_volts:.3f},{mq135_volts:.3f}\n')
        except IOError as e:
            print(f'Error writing to log file: {e}')
            exit(1)

    def run(self):
        self.setup_spi()
        self.setup_actuator()
        while True:
            try:
                mq2_volts = self.read_adc(self.config['mq2_channel'])
                mq7_volts = self.read_adc(self.config['mq7_channel'])
                mq135_volts = self.read_adc(self.config['mq135_channel'])
                self.check_thresholds('mq2', mq2_volts)
                self.check_thresholds('mq7', mq7_volts)
                self.check_thresholds('mq135', mq135_volts)
                self.log_reading(mq2_volts, mq7_volts, mq135_volts)
                time.sleep(5)
            except KeyboardInterrupt:
                print('\nExiting on user request.')
                break
            except Exception as e:
                print(f'Error in main loop: {e}')
                break
        self.spi.close()
        self.actuator.off()

if __name__ == '__main__':
