import time
import signal
import logging
from gpiozero import DistanceSensor, AngularServo
from pid import PIDController

class BalanceBeamController:
    def __init__(self):
        self.sensor = DistanceSensor(echo_pin=24, trigger_pin=23, max_distance=0.100)
        self.servo = AngularServo(25, min_angle=0, max_angle=50)
        self.pid = PIDController(0.5, 0.00, 0.4)
        self.setpoint = 0.25
        self.tolerance = 0.03
        self.max_error = 0.25
        self.consecutive_readings = []

    def read_sensor(self):
        try:
            return self.sensor.distance
        except Exception as e:
            logging.error(f"Failed to read sensor: {e}")
            return None

    def write_servo(self, angle):
        try:
            self.servo.angle = angle
        except Exception as e:
            logging.error(f"Failed to write servo: {e}")

    def control_loop(self):
        while True:
            distance = self.read_sensor()
            if distance is not None:
                error = self.setpoint - distance
                if abs(error) > self.max_error:
                    logging.warning(f"Error exceeds maximum: {error}")
                else:
                    angle = self.pid.update(error)
                    self.write_servo(angle)
                    self.consecutive_readings.append(abs(error) <= self.tolerance)
                    if self.consecutive_readings[-3:] == [True, True, True]:
                        break
                logging.info(f"Distance: {distance}, Error: {error}, Angle: {angle}")
            time.sleep(0.1)

    def cleanup(self):
        try:
            self.servo.detach()
        except Exception as e:
            logging.error(f"Failed to detach servo: {e}")
        try:
            self.sensor.close()
        except Exception as e:
            logging.error(f"Failed to close sensor: {e}")

def main():
    logging.basicConfig(level=logging.INFO)
    controller = BalanceBeamController()
    try:
        controller.control_loop()
    except KeyboardInterrupt:
        pass
    finally:
        controller.cleanup()

if __name__ == "__main__":
    main()

