def load_config():
    global config
    try:
        with open('config.json', 'r') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        config = {
            'trigger_pins': [17, 22, 24],
            'echo_pins': [18, 23, 25],
            'offsets': [0.0, 0.0, 0.0],
            'max_distances': [200.0, 200.0, 200.0],
            'alert_threshold_low': 10.0,
            'alert_threshold_high': 180.0,
            'alert_repeat_delay': 60,
            'log_file': 'water_level.log'
        }
    finally:
        logging.basicConfig(filename=config['log_file'], level=logging.INFO)

def setup_sensors():
    global sensors
    for trigger_pin, echo_pin, offset, max_distance in zip(
            config['trigger_pins'], config['echo_pins'], config['offsets'], config['max_distances']):
        try:
            sensor = DistanceSensor(trigger_pin=trigger_pin, echo_pin=echo_pin, max_distance=max_distance)
            sensor.offset = offset
            sensors.append(sensor)
        except Exception as e:
            logging.error(f'Failed to setup sensor on pins {trigger_pin}/{echo_pin}: {str(e)}')
            exit(0)

def measure_distance(sensor):
    try:
        return sensor.distance
    except Exception as e:
        logging.error(f'Failed to measure distance on sensor {sensor.trigger_pin}/{sensor.echo_pin}: {str(e)}')
        return None

def check_alerts(avg_level):
    for alert_type, message in alert_types.items():
        if (alert_type == 'low' and avg_level < config['alert_threshold_low']) or \
                (alert_type == 'high' and avg_level > config['alert_threshold_high']):
            if time.time() - alert_last_sent.get(alert_type, 0) > config['alert_repeat_delay']:
                logging.info(message)
                alert_last_sent[alert_type] = time.time()

def main_loop():
    while True:
        distances = [measure_distance(sensor) for sensor in sensors]
        valid_distances = [d for d in distances if d is not None]
        if valid_distances:
            avg_level = median(valid_distances)
            logging.info(f'Average water level: {avg_level}')
            check_alerts(avg_level)
        else:
            logging.error('All sensors failed.')
        time.sleep(5)

def sig_handler(sig, frame):
    logging.info('Exiting...')
    for sensor in sensors:
        sensor.close()
    Device.cleanup()
    exit(0)

if __name__ == '__main__':
    load_config()
    signal.signal(signal.SIGINT, sig_handler)
    signal.signal(signal.SIGTERM, sig_handler)
    setup_sensors()
    main_loop()

