        self._box = Box()
        self._button = Button(2)
        self._button.when_pressed = self._on_button_press
        self._button.when_released = self._on_button_release
        self._cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        self._recognizer = cv2.face.EigenFaceRecognizer_create()
        self._load_model()
        self._picamera2 = Picamera2()
        self._picamera2.configure({
            'make': 'picamera2',
            'format': 'bgr',
            'width': 640,
            'height': 480,
            'framerate': 24,
            'encoders': [{
                'output': FileOutput('output.jpg'),
                'quality': Quality(100)
            }],
            'controls': {
                'sharpness': 0,
                'contrast': 0,
                'saturation': 0,
                'brightness': 0.5,
                'iso': 400,
                'video_stabilisation': False,
                'exposure_mode': 'auto',
                'meter_mode': 'average',
                'awb_mode': 'auto',
                'antibanding': 'auto'
            }
        })
        self._picamera2.start()

