import numpy as np
from datetime import datetime
from picamera2 import Picamera2, Preview, Request
from picamera2.encoders import Quality
from picamera2.outputs import FileOutput
from picamera2.mmal_params import controls
from picamera2.stats import MotionStatistics
from gpiozero import Button
from paho.mqtt import client as mqtt_client

class MotionDetector:
    def __init__(self):
        self.picam2 = Picamera2()
        self.picam2.configure_interface(controls.CAMERA_SENSOR_MODE_STILL, controls.CAMERA_SENSOR_MODE_VIDEO)
        self.picam2.set_controls({"sharpness": 50, "saturation": 0, "contrast": 0, "iso": 400, "exposure_mode": "auto"})
        self.picam2.start()
        self.background = None
        self.last_motion = None
        self.min_motion_frames = 8
        self.min_upload_seconds = 30
        self.delta_thresh = 5
        self.min_area = 5000
        self.saved_imgs_dir = "./saved_imgs/"
        if not os.path.exists(self.saved_imgs_dir):
            os.makedirs(self.saved_imgs_dir)
        self.mqtt_client = mqtt_client.Client()
        self.mqtt_client.connect("mqtt.eclipse.org", 1883, 60)
        self.button = Button(2)

    def capture_frame(self):
        try:
            return self.picam2.capture_array()
        except Exception as e:
            print(f"Failed to capture frame: {e}")
            return None

    def update_background(self, frame):
        if self.background is None:
            self.background = frame.copy()
        else:
            cv2.accumulateWeighted(frame, self.background, 0.95)

    def detect_motion(self, frame):
        try:
            diff = cv2.absdiff(self.background, frame)
            moving = diff > self.delta_thresh
            stats = MotionStatistics(moving)
            for blob in stats.blobs:
                if blob.area > self.min_area:
                    return True
            return False
        except Exception as e:
            print(f"Failed to detect motion: {e}")
            return False

    def save_frame(self, frame):
        try:
            timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
            filename = f"{self.saved_imgs_dir}/{timestamp}.jpg"
            cv2.imwrite(filename, frame)
            self.mqtt_client.publish("motion_detected", f"Image saved to {filename}")
        except Exception as e:
            print(f"Failed to save frame: {e}")

    def on_shutdown(self, signum, frame):
        print("Shutting down...")
        self.picam2.stop()
        self.mqtt_client.disconnect()
        self.mqtt_client.loop_stop()
        exit(0)

    def run(self):
        signal.signal(signal.SIGINT, self.on_shutdown)
        signal.signal(signal.SIGTERM, self.on_shutdown)
        try:
            time.sleep(2.0)
            while True:
                frame = self.capture_frame()
                if frame is not None:
                    self.update_background(frame)
                    if self.detect_motion(frame):
                        if self.last_motion is None or time.time() - self.last_motion > self.min_upload_seconds:
                            self.save_frame(frame)
                            self.last_motion = time.time()
        except Exception as e:
            print(f"Error: {e}")
        finally:
            self.on_shutdown(None, None)

if __name__ == "__main__":
    detector = MotionDetector()
    detector.run()

