                sys.stderr.write(f"Error writing to serial port: {e}\n")


def main():
    with SerialPort('/dev/rfcomm4') as ser:
        if ser is None:
            return
        try:
            while True:
                line = input('> ')
                if line == 'q':
                    break
                ser.write_line(line)
        except KeyboardInterrupt:
            pass


if __name__ == "__main__":
    main()
