            except Exception as e:
                self.logger.error(f"Failed to initialize sensor: {e}")
                time.sleep(2)
        else:
            self._exit_gracefully(None, None, 1)

    def _setup_camera(self):
        if self.config["enable_camera"]:
            try:
                self.camera = picamera2.Picamera2()
                self.logger.info("Initialized camera")
            except Exception as e:
                self.logger.warning(f"Failed to initialize camera: {e}")

    def _start_sampling_thread(self):
        threading.Thread(target=self._sample_sensor, daemon=True).start()

    def _sample_sensor(self):
        while True:
            try:
                frame = self.sensor.get_frame_data()
                self.frames[self.frame_index] = frame
                self.frame_index = (self.frame_index + 1) % 300
                if self.camera is not None:
                    self._capture_image()
                self._plot_frame(frame)
                time.sleep(1 / self.config["sampling_rate"])
            except Exception as e:
                self.logger.error(f"Failed to sample sensor: {e}")

    def _capture_image(self):
        try:
            self.camera.capture_file(f"image_{int(time.time())}.jpg")
            self.logger.info("Captured image")
        except Exception as e:
            self.logger.error(f"Failed to capture image: {e}")

    def _plot_frame(self, frame):
        try:
            plt.imshow(frame, cmap='jet', interpolation='nearest')
