        except Exception as e:
            self.logger.error(f"Failed to plot frame: {e}")

    def _exit_gracefully(self, signum, frame, exit_code=0):
        self.logger.info("Exiting gracefully")
        if self.camera is not None:
            self.camera.close()
        if self.bus is not None:
            self.bus.close()
        logging.shutdown()
        exit(exit_code)

