import logging
import signal
import threading
import io
import numpy as np
import cv2
from picamera2 import Picamera2, Preview, Request
from websocket_handler import WebSocketHandler

class CameraStreamBuffer:
    def __init__(self, websocket_handler: WebSocketHandler):
        assert isinstance(websocket_handler, WebSocketHandler)
        self.websocket_handler = websocket_handler
        self.lock = threading.Lock()
        self.buffer = io.BytesIO()
        self.frame_start_marker = b'\xff\xd8'
        self.frame_end_marker = b'\xff\xd9'

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            pos = self.buffer.tell()
            self.buffer.seek(0)
            while True:
                start = self.buffer.find(self.frame_start_marker, 1)
                if start < 0:
                    break
                end = self.buffer.find(self.frame_end_marker, start)
                if end < 0:
                    break
                frame = self.buffer.read(end - start + 2)
                self.buffer.seek(0)
                self.buffer.write(self.buffer.read()[end - start + 2:])
                self.buffer.truncate()
                if self.websocket_handler.has_connections():
                    self.websocket_handler.broadcast(frame)

    def flush(self):
        with self.lock:
            self.buffer.flush()

class MotionDetectionBuffer(CameraStreamBuffer):
    def __init__(self, websocket_handler: WebSocketHandler, detect_motion_function):
        super().__init__(websocket_handler)
        assert callable(detect_motion_function)
        self.detect_motion_function = detect_motion_function
        self.previous_frame = None
        self.current_frame = None

    def _convert_to_opencv_frame(self, frame_data):
        try:
            return cv2.imdecode(np.frombuffer(frame_data, dtype=np.uint8), cv2.IMREAD_COLOR)
        except Exception as e:
            logging.error(f"Failed to decode frame: {e}")
            return None

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            pos = self.buffer.tell()
            self.buffer.seek(0)
            while True:
                start = self.buffer.find(self.frame_start_marker, 1)
                if start < 0:
                    break
                end = self.buffer.find(self.frame_end_marker, start)
                if end < 0:
                    break
                frame = self.buffer.read(end - start + 2)
                self.buffer.seek(0)
                self.buffer.write(self.buffer.read()[end - start + 2:])
                self.buffer.truncate()
                self.current_frame = self._convert_to_opencv_frame(frame)
                if self.previous_frame is not None and self.current_frame is not None:
                    try:
                        self.detect_motion_function(self.previous_frame, self.current_frame)
                    except Exception as e:
                        logging.error(f"Error in motion detection function: {e}")
