import io
import logging
import time
import numpy as np
import cv2
from picamera2 import Picamera2, MappedArray, Request
from gpiozero import Button
from paho.mqtt import client as mqtt_client
from adafruit_circuitplayground.express import cpx

class CameraStreamBuffer:
    def __init__(self, c):
        self.c = c
        self.b = io.BytesIO()
        self.prev_frame = None

    def write(self, d):
        try:
            self.b.write(d)
            if self.c.current_configuration()['encode']:
                frame_type = self.c.current_configuration()['encode']['frame_type']
                if frame_type != 1:
                    self.flush()
        except Exception as e:
            logging.error(f"I/O error: {e}")

    def flush(self):
        self.b.flush()
        self.b.seek(0)
        self.b.truncate(0)

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.b = io.BytesIO()
        self.first_frame = True

    def write(self, d):
        try:
            self.b.write(d)
            if d.startswith(b'\xff\xd8'):
                self.flush()
        except Exception as e:
            logging.error(f"Decode error: {e}")

    def flush(self):
        self.b.flush()
        self.b.seek(0)
        frame = cv2.imdecode(np.frombuffer(self.b.read(), np.uint8), cv2.IMREAD_COLOR)
        if self.first_frame:
            self.first_frame = False
            self.prev_frame = frame
        else:
            self.f(self.prev_frame, frame)
            self.prev_frame = frame
        self.b.seek(0)
        self.b.truncate(0)

def motion_detected(prev_frame, current_frame):
    diff = cv2.absdiff(prev_frame, current_frame)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    blur = cv2.GaussianBlur(gray, (5, 5), 0)
    _, threshold = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
    dilated = cv2.dilate(threshold, None, iterations=3)
    contours, _ = cv2.findContours(dilated, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    for c in contours:
        if cv2.contourArea(c) < 5000:
            continue
        x, y, w, h = cv2.boundingRect(c)
        cv2.rectangle(current_frame, (x, y), (x+w, y+h), (0, 255, 0), 2)
    cv2.imshow('frame', current_frame)
    cv2.waitKey(1)

