def display_gif(file_path, loop_count=0):
    try:
        image = Image.open(file_path)
    except Exception as e:
        logging.error(f"Failed to open file {file_path}: {e}")
        return

    try:
        duration = image.info['duration'] / 1000.0  # Convert to seconds
    except KeyError:
        logging.error(f"Missing duration in file {file_path}")
        return

    try:
        loop_count = image.info['loop_count']
    except KeyError:
        logging.warning(f"Missing loop count in file {file_path}, defaulting to infinite")

    frame_number = 0
    while True:
        try:
            image.seek(frame_number)
        except EOFError:
            frame_number = 0
            if loop_count > 0 and image.tell() >= loop_count:
                break
        except Exception as e:
            logging.error(f"Failed to seek to frame {frame_number} in file {file_path}: {e}")
            break

        try:
            resized_image = image.resize((device.width, device.height), Image.NEAREST)
        except Exception as e:
            logging.error(f"Failed to resize image {file_path} to fit on display: {e}")
            break

