            return None

        try:
            # Assuming the temperature is the first float in the line
            temp = float(line.split()[0])
        except ValueError:
            print(f"Failed to parse temperature from line: {line}")
            return None

        return temp

    def close_port(self):
        if self.ser is not None:
            self.ser.close()

    def run(self):
        if not self.open_port():
            return

        def signal_handler(sig, frame):
            print('\nExiting...')
            self.close_port()
            exit(0)

        signal.signal(signal.SIGINT, signal_handler)

        while True:
            temp = self.read_data()
            if temp is not None:
                print(f"Temperature: {temp:.1f} C")
            time.sleep(0.5)


if __name__ == "__main__":
