            time.sleep(0.5)
            status = self.bus.read_byte_data(0x38, 0x71)
            if (status & 0x18) != 0x18:
                logging.error("Status check failed")
                return False
        except:
            logging.error("Failed to open I2C bus")
            return False

    def get_temperature_and_humidity(self):
        for attempt in range(5):
            try:
                self.bus.write_i2c_block_data(0x38, 0xAC, [0x33, 0x00])
                for _ in range(10):
                    status = self.bus.read_byte_data(0x38, 0x71)
                    if status & 0x80 == 0:
                        break
                    time.sleep(0.1)
                else:
                    logging.warning("Timeout waiting for measurement")
                    continue
                data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
                raw_humidity = (data[0] << 16) | (data[1] << 8) | data[2]
                raw_temperature = (data[3] << 16) | (data[4] << 8) | (data[3] >> 4)
