                if crc != data[6]:
                    logging.warning("CRC failure")
                    continue
                temperature = raw_temperature / 5242.88 - 50
                humidity = raw_humidity / 1048576 * 100
                return (temperature, humidity, crc != data[6])
            except:
                logging.error("Error during measurement")
            time.sleep(2)
        return (None, None, True)

    def crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc <<= 1
        return crc

    def cleanup(self):
        if self.bus is not None:
            self.bus.close()

    def __del__(self):
        self.cleanup()

