        self.bus = None
        try:
            self.bus = smbus2.SMBus(1)
            status = self.bus.read_byte_data(0x38, 0x71)
        except (IOError, OSError) as e:
            logging.error(f"I/O error: {e}")
            self.bus = None

    def measure(self):
        if self.bus is None:
            return (None, None, True)

        try:
            self.bus.write_i2c_block_data(0x38, 0xAC, [0x33, 0x00])
            for _ in range(100):
                status = self.bus.read_byte_data(0x38, 0x71)
                if status & 0x80 == 0:
                    break
                time.sleep(0.01)
            else:
                logging.error("Timeout waiting for measurement")
                return (None, None, True)

            data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
            crc = data[6]
            crc_error = False

            poly = 0x31
            crc_calc = 0xFF
            for byte in data[:6]:
                for _ in range(8):
                    msb = crc_calc >> 7
                    crc_calc = (crc_calc << 1) | ((byte >> 7) & 1)
                    byte <<= 1
                    if msb:
