from gpiozero import DigitalInputDevice, DigitalOutputDevice, GPIOZeroError

class DHT22:
    def __init__(self, data_pin):
        self.data_pin = DigitalInputDevice(data_pin, pull_up_resistor=1)
        self.bits = []
        self.temperature = None
        self.humidity = None

    def read(self):
        self.data_pin.drive_low()
        time.sleep(0.018)
        self.data_pin.drive_high()
        time.sleep(0.00004)
        self.data_pin.input_with_pull(pull_up_resistor=1)
        if not self.data_pin.wait_for_falling(timeout=0.0008):
            return False
        if not self.data_pin.wait_for_rising(timeout=0.0008):
            return False
        for _ in range(40):
            start = time.perf_counter()
            if not self.data_pin.wait_for_rising(timeout=0.0005):
                return False
            pulse = time.perf_counter() - start
            if pulse > 0.000028:
                self.bits.append(1)
            else:
                self.bits.append(0)
        if sum(self.bits[i] << (7 - i % 8) for i in range(40)) != 0x3FF:
            return False
        self.humidity = sum(self.bits[i] << (7 - i % 8) for i in range(0, 16)) / 10
        self.temperature = (sum(self.bits[i] << (7 - i % 8) for i in range(16, 32)) - 512) / 10
