        self.data_pin.drive_low()
        time.sleep(0.018)
        self.data_pin.drive_high()
        time.sleep(0.00004)
        self.data_pin.input_with_pull(pull_up_resistor=1)
        if not self.data_pin.wait_for_falling(timeout=0.0008):
            return False
        if not self.data_pin.wait_for_rising(timeout=0.0008):
            return False
