from gpiozero import PWMOutputDevice, Device
from gpiozero.pins.pigpio import PiGPIOFactory

class FanController:
    def __init__(self, gpio_pin=14, frequency=100):
        self.fan = PWMOutputDevice(gpio_pin, frequency=frequency, pin_factory=PiGPIOFactory())
        self.shutdown_event = Device._shutdown_event
        self.shutdown_event.clear()
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)
        logging.basicConfig(filename='fan_controller.log', level=logging.INFO,
                            format='%(asctime)s:%(levelname)s:%(message)s')

    def read_cpu_temp(self):
        try:
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as file:
                temp = float(file.read().strip()) / 1000
        except Exception as e:
            logging.error(f"Failed to read CPU temperature: {str(e)}")
            return None
        return temp

    def set_fan_speed(self, temp):
        if temp is None:
            self.fan.value = 0
            logging.info(f"Failed to read CPU temperature. Fan speed set to 0%.")
            return
        if temp > 70:
            duty_cycle = 1.0
        elif temp > 60:
            duty_cycle = 0.85
        elif temp > 50:
            duty_cycle = 0.7
        elif temp > 40:
            duty_cycle = 0.5
        elif temp > 32:
            duty_cycle = 0.25
        elif temp > 25:
            duty_cycle = 0.15
        else:
            duty_cycle = 0.0
        self.fan.value = duty_cycle
        logging.info(f"Current temperature: {temp}°C. Fan speed set to {int(duty_cycle * 100)}%.")

    def cleanup(self, *args):
        self.fan.close()
        logging.info("Fan controller shut down.")
        self.shutdown_event.set()

    def run(self):
        while not self.shutdown_event.is_set():
            self.set_fan_speed(self.read_cpu_temp())
            time.sleep(5)

if __name__ == "__main__":
    controller = FanController()
    controller.run()

