import smbus2
import datetime
import time

# BME280 registers
REG_HUMIDITY_OS = 0xF2
REG_CTRL_MEAS = 0xF4
REG_CALIB_START = 0xA1
REG_CALIB_END = 0xE7
REG_HUMIDITY_DATA = 0xFD

# BME280 constants
T_FINE = 20000

# BME280 coefficients
dig_H = [0]*6

# I2C bus 1
bus = smbus2.SMBus(1)

# BME280 I2C address
BME280_I2C_ADDR = 0x76

def read_coeff():
    global dig_H
    try:
        for i in range(6):
            if i == 3:
                dig_H[i] = bus.read_byte_data(BME280_I2C_ADDR, REG_CALIB_START + i + 1)
                dig_H[i] = (dig_H[i] << 4) | (bus.read_byte_data(BME280_I2C_ADDR, REG_CALIB_START + i) & 0x0F)
            else:
                dig_H[i] = bus.read_byte_data(BME280_I2C_ADDR, REG_CALIB_START + i)
    except OSError as e:
        print(f"Error reading BME280 coefficients: {e}")
        exit(1)

def read_humidity():
    try:
        raw_humidity = bus.read_i2c_block_data(BME280_I2C_ADDR, REG_HUMIDITY_DATA, 2)
        raw_humidity = (raw_humidity[0] << 8) | raw_humidity[1]
        var_H = (raw_humidity - ((dig_H[0] * (raw_humidity**2)) / (1 << 40))) * ((1 << 16) * dig_H[1])
        var_H = (var_H - ((dig_H[3] * (var_H**2)) / (1 << 30))) / (1 << 15)
        var_H = var_H * (1 - (dig_H[4] * var_H) / (1 << 15))
        if var_H > 100:
            var_H = 100
        elif var_H < 0:
            var_H = 0
        return var_H
    except OSError as e:
        print(f"Error reading BME280 humidity: {e}")
        return None

def main():
    try:
        # BME280 sensor initialisation
        bus.write_byte_data(BME280_I2C_ADDR, REG_HUMIDITY_OS, 0x01)
        bus.write_byte_data(BME280_I2C_ADDR, REG_CTRL_MEAS, 0x3F)
        read_coeff()

        for i in range(5):
            humidity = read_humidity()
            if humidity is not None:
                timestamp = datetime.datetime.now().isoformat()
                if humidity < 30:
                    status = "too_dry"
                elif humidity < 40:
                    status = "dry"
                elif humidity < 60:
                    status = "comfortable"
                else:
                    status = "too_humid"
                print(f"{timestamp}: {humidity}% {status}")
            time.sleep(2)
    except OSError as e:
        print(f"Error initialising or reading BME280: {e}")
    finally:
        bus.close()

if __name__ == "__main__":
    main()

