import serial
import time
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
import sys

class HeatmapDisplay:
    def __init__(self, port, baud, timeout):
        self.ser = None
        try:
            self.ser = serial.Serial(port, baud, timeout=timeout)
        except (serial.SerialException, serial.SerialTimeoutException) as e:
            print(f"Failed to open serial port: {e}")
            sys.exit(1)

        self.frame = np.zeros((24, 32))
        self.fig, self.ax = plt.subplots()
        self.im = self.ax.imshow(self.frame, cmap='inferno', interpolation='nearest')
        self.ani = FuncAnimation(self.fig, self.update, interval=100)

    def update(self, data):
        try:
            line = self.ser.readline().decode().strip()
            if not line:
                return
            data = line.split(',')
            if len(data) != 768:
                return
            frame_data = [float(d) for d in data if d.isdigit()]
            if len(frame_data) != 768:
                return
            self.frame = np.array(frame_data).reshape((24, 32))
        except (serial.SerialException, serial.SerialTimeoutException) as e:
            print(f"Serial I/O error: {e}")
            sys.exit(1)

    def run(self):
        try:
            plt.show()
        except KeyboardInterrupt:
            print("User interrupted the program.")
        finally:
            if self.ser:
                self.ser.close()
            plt.close()

if __name__ == "__main__":
    display = HeatmapDisplay("/dev/ttyUSB0", 9600, 0.1)
    display.run()

