from requests.exceptions import RequestException
import requests

class GPIOError(Exception):
    pass

class GPIOInterrupt(GPIOError):
    pass

class GPIO(InputDevice):
    def __init__(self, pin=17):
        super(GPIO, self).__init__(pin, pull_up=True)

    def wait_for_interrupt(self, timeout=None):
        try:
            return super(GPIO, self).wait_for_interrupt(timeout)
        except InterruptError as e:
            raise GPIOInterrupt(e)

def send_alert():
    try:
        response = requests.post('http://example.com/alert', json={"alert": "Power failure detected"}, timeout=5)
