from optional import OptionalModule

# Optional RPi.GPIO import
gpio = OptionalModule('RPi.GPIO')

# Vader lexicon
vader_lexicon = {
    'happy': 0.5, 'joy': 0.4, 'cheer': 0.3, 'cheery': 0.2, 'smile': 0.1,
    'sad': -0.5, 'unhappy': -0.4, 'downcast': -0.3, 'down': -0.2, 'sorrow': -0.1,
    # Add more words here...
}

def sentiment_analysis(sentence: str) -> Optional[str]:
    words = sentence.lower().split()
    scores = [vader_lexicon.get(word, 0.0) for word in words]
    avg_score = sum(scores) / len(scores) if scores else 0.0

    if avg_score > 0.2:
        return 'Positive'
    elif avg_score < -0.2:
        return 'Negative'
    else:
        return 'Neutral'

def led_control(sentiment: str) -> None:
    if not gpio.is_available():
        return

    try:
        gpio.setup(17, gpio.OUT)  # Green LED on GPIO 17
        gpio.setup(18, gpio.OUT)  # Red LED on GPIO 18

        if sentiment == 'Positive':
            gpio.output(17, gpio.HIGH)  # Turn green LED on
            time.sleep(2)
            gpio.output(17, gpio.LOW)  # Turn green LED off
        elif sentiment == 'Negative':
            gpio.output(18, gpio.HIGH)  # Turn red LED on
            time.sleep(2)
            gpio.output(18, gpio.LOW)  # Turn red LED off
    finally:
        gpio.cleanup()

def main() -> None:
    try:
        sentence = input("Enter a sentence: ")
        sentiment = sentiment_analysis(sentence)
        print(f"Sentiment: {sentiment}")
        led_control(sentiment)
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
