import smbus2
import time
import signal
from fcntl import ioctl

class BH1750:
    def __init__(self, bus, addr):
        self.bus = bus
        self.addr = addr
        try:
            self.bus.write_byte(self.addr, 0x20)
        except (OSError, IOError) as e:
            print(f"Error initializing BH1750: {e}")
            exit(1)

    def read_illuminance(self):
        try:
            data = self.bus.read_i2c_block_data(self.addr, 0x20, 2)
            raw_value = (data[0] << 8) | data[1]
            return (raw_value * 1.2) / 1.2
        except (OSError, IOError) as e:
            print(f"Error reading BH1750: {e}")
            return None

def main():
    bus = smbus2.SMBus(1)
    sensor = BH1750(bus, 0x23)

    def exit_handler(signal, frame):
        bus.close()
        print("\nExiting...")
        exit(0)

    signal.signal(signal.SIGINT, exit_handler)
    signal.signal(signal.SIGTERM, exit_handler)

    while True:
        illuminance = sensor.read_illuminance()
        if illuminance is not None:
            print(f"Illuminance: {illuminance:.2f} lux")
        time.sleep(3)

if __name__ == "__main__":
    main()

