import pigpio
import threading
import signal
from gpiozero import Device
from gpiozero.pins.pigpio import PiGPIOFactory
from picamera2 import Picamera2
from adafruit_circuitpython_mqtt import MQTT
from paho.mqtt.client import Client

class GPIOControl:
    def __init__(self, gpio, value_list, initial_value=None):
        self.gpio = gpio
        self.value_list = value_list
        self._pi = pigpio.pi()
        if not self._pi.connected:
            raise Exception("Failed to connect to pigpio daemon")
        if self.gpio not in range(0, 54):
            raise ValueError("Invalid GPIO pin number")
        if initial_value is not None and initial_value not in self.value_list:
            raise ValueError("Invalid initial value")
        self._pi.set_mode(self.gpio, pigpio.OUTPUT)
        self._pi.write(self.gpio, self.value_list[0] if initial_value is None else initial_value)
        self._lock = threading.Lock()
        signal.signal(signal.SIGINT, self._shutdown)

    def _shutdown(self, signum=None, frame=None):
        self._pi.set_mode(self.gpio, pigpio.INPUT)
        self._pi.stop()
        Device.close_all()

class OutputPin(GPIOControl):
    def __init__(self, gpio, value_list, initial_value=None):
        super().__init__(gpio, value_list, initial_value)
        self._current_value = self.value_list[0] if initial_value is None else initial_value

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError("Invalid value")
        self._pi.write(self.gpio, value)
        self._current_value = value

class TriggerPin(OutputPin):
    def __init__(self, gpio, pulse_duration, value_list, initial_value=None, pulse_high=True):
        super().__init__(gpio, value_list, initial_value)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high

    def trigger(self):
        with self._lock:
            if self._current_value == self.value_list[1 if self.pulse_high else 0]:
                raise Exception("Cannot trigger a pulse while already in the active state")
            self._pi.set_mode(self.gpio, pigpio.OUTPUT)
            self._pi.write(self.gpio, self.value_list[1 if self.pulse_high else 0])
            threading.Timer(self.pulse_duration / 1e6, self._return_to_initial).start()

    def _return_to_initial(self):
        self._pi.write(self.gpio, self.value_list[0 if self.pulse_high else 1])

import logging
import signal
import time
from datetime import datetime
from typing import Callable

import gpiozero
import paho.mqtt.client as mqtt
import zmq

class PIDHandler:
    def __init__(self, pwm: bool = True):
        self.pwm = pwm
        self.global_err_state = False
        self.last_msg = datetime.now()
        self.subscription_callbacks = []

        try:
            if self.pwm:
                self.error_output = gpiozero.PWMOutputDevice(18, frequency=1000)
            else:
                self.error_output = gpiozero.OutputDevice(15)
        except RuntimeError as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.error_output = None

        self.update_error_output()

        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def update_error_output(self):
        if self.error_output is not None:
            if self.pwm:
                self.error_output.value = 1.0 if self.global_err_state else 0.0
            else:
                self.error_output.on if self.global_err_state else self.error_output.off

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self, client: mqtt.Client, userdata, message):
        self.last_msg = datetime.now()
        for callback in self.subscription_callbacks:
            callback(client, userdata, message)

    def cleanup(self, *args):
        if self.error_output is not None:
            self.error_output.close()
        exit(0)

    def subscribe(self, topic: str, callback: Callable[[mqtt.Client, dict, mqtt.MQTTMessage], None]):
        self.subscription_callbacks.append(callback)

# Example usage:

def on_connect(client: mqtt.Client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe("my/topic")

def on_message(client: mqtt.Client, userdata, message):
    print(f"Received message {message.payload.decode()} on {message.topic}")

if __name__ == "__main__":
    pid_handler = PIDHandler()
    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_message = pid_handler.handle_message
    client.connect("mqtt.eclipse.org", 1883, 60)

    pid_handler.subscribe("my/topic", on_message)

    while True:
        try:
            client.loop(timeout=1.0)
            time.sleep(0.1)
            if (datetime.now() - pid_handler.last_msg).total_seconds() > 20:
                pid_handler.set_error_output(True)
        except KeyboardInterrupt:
            pid_handler.cleanup()

