from gpiozero.exc import GPIOZeroError

# Set up logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

# Set up the backlight control GPIO device
backlight = OutputDevice(24, active_high=False, initial_value=False)

# Set up the TCP server socket
server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
server_socket.bind(('0.0.0.0', 9100))
server_socket.listen(1)
server_socket.settimeout(5)

def handle_client(client_socket):
    try:
        while True:
            request = client_socket.recv(64).decode('utf-8')
            if not request:
                break
            if request.strip().lower() == 'on':
                backlight.on()
                client_socket.sendall('backlight on'.encode('utf-8'))
            elif request.strip().lower() == 'off':
                backlight.off()
                client_socket.sendall('backlight off'.encode('utf-8'))
            else:
                client_socket.sendall('unknown command'.encode('utf-8'))
    except Exception as e:
        logging.error(f'Error handling client: {e}')
    finally:
        client_socket.close()

def main():
    try:
        while True:
            try:
                client_socket, addr = server_socket.accept()
                logging.info(f'Accepted connection from {addr}')
                handle_client(client_socket)
            except socket.timeout:
                pass
            except Exception as e:
                logging.error(f'Error accepting connection: {e}')
    except KeyboardInterrupt:
        logging.info('Received interrupt, shutting down')
    finally:
        server_socket.close()
        backlight.close()

if __name__ == '__main__':
    main()

