        except pigpio.error as e:
            raise GPIOError(f"Failed to set pin {self.pin_number} to {value}: {e}")

    def shutdown(self):
        try:
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
            self.pi.stop()
        except pigpio.error as e:
