import csv
import time
import smbus2
import signal
from statistics import mean
from datetime import datetime

class MPU6050:
    def __init__(self, bus=1, addr=0x68):
        self.bus = smbus2.SMBus(bus)
        self.addr = addr
        self.gyro_scale = 131.0
        self.calibration = [0, 0, 0]

    def write_register(self, reg, data):
        try:
            self.bus.write_byte_data(self.addr, reg, data)
        except IOError as e:
            print(f"Failed to write to register {reg} due to {str(e)}")
            exit(1)

    def read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.addr, reg)
        except IOError as e:
            print(f"Failed to read from register {reg} due to {str(e)}")
            exit(1)

    def read_gyro(self):
        data = self.bus.read_i2c_block_data(self.addr, 0x43, 6)
        return [(v << 8 | self.read_register(reg + 1)) for v, reg in zip(data[::2], data[1::2])]

    def calibrate(self, duration=5):
        start = time.time()
        calibration = []
        while time.time() - start < duration:
            gyro_data = self.read_gyro()
            calibration.append(gyro_data)
        self.calibration = [mean(x) for x in zip(*calibration)]

    def log_gyro(self, file):
        try:
            with open(file, 'a') as f:
                writer = csv.writer(f)
                timestamp = time.time()
                raw_data = self.read_gyro()
                calibrated_data = [x - b for x, b in zip(raw_data, self.calibration)]
                writer.writerow([timestamp] + raw_data + calibrated_data)
        except IOError as e:
            print(f"Failed to write to file {file} due to {str(e)}")
            exit(1)

def main():
    mpu = MPU6050()
    mpu.write_register(0x6B, 0x00)
    mpu.write_register(0x1B, 0x00)

    if '--calibrate' in sys.argv:
        mpu.calibrate()
        return

    duration = 60
    sample_rate = 20
    if len(sys.argv) > 1:
        duration = int(sys.argv[1])
    if len(sys.argv) > 2:
        sample_rate = int(sys.argv[2])

    dt = 1 / sample_rate
    start = time.time()
    while time.time() - start < duration:
        mpu.log_gyro('gyro.csv')
        time.sleep(dt)

if __name__ == "__main__":
    try:
        main()
    except IOError as e:
        print(f"I/O error occurred: {str(e)}")
    except Exception as e:
        print(f"An error occurred: {str(e)}")
    finally:
        mpu.bus.close()

