from adafruit_circuitplayground.express import cpx

# MQTT broker details
broker_url = 'broker.hivemq.com'
client_id = 'RaspberryPi'

# I2C bus initialization
try:
    i2c = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Failed to initialize I2C bus: {e}")
    exit(1)

# TCS34725 sensor initialization
try:
    sensor = adafruit_tcs34725.TCS34725(i2c, integration_time=adafruit_tcs34725.INTEGRATION_TIME_50MS, gain=adafruit_tcs34725.GAIN_4X)
except Exception as e:
    print(f"Failed to initialize TCS34725 sensor: {e}")
    exit(1)

def get_sensor_color_data():
    try:
        r, g, b, c = sensor.color_rgb_bytes
        return (r, g, b, c)
    except Exception as e:
        print(f"Failed to read sensor color data: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        img = Image.open(image_path)
        img.thumbnail((100, 100))
        colors = img.getcolors()
        colors.sort(reverse=True)
        dominant_color = colors[0][1]
        return dominant_color
    except FileNotFoundError:
        print("Image not found.")
        return (0, 0, 0)
    except Exception as e:
        print(f"Failed to find dominant image color: {e}")
        return (0, 0, 0)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe("topic")

def on_message(client, userdata, msg):
    print(f"{msg.topic} {msg.payload}")

def main():
    client = mqtt_client.Client(client_id)
    client.on_connect = on_connect
    client.on_message = on_message
    client.connect(broker_url, 1883)
    client.loop_start()

    try:
        while True:
            sensor_data = get_sensor_color_data()
            image_data = find_dominant_image_color('image.jpg')
            print(f"Sensor color data: {sensor_data}, Dominant image color: {image_data}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nShutting down...")
    finally:
        client.loop_stop()
        client.disconnect()
        i2c.deinit()

if __name__ == "__main__":
    main()

