import signal
import time
from gpiozero import LED
from gpiozero.exc import GPIOError, GPIOPinInUse, GPIOPinMissing

class LEDController:
    def __init__(self):
        self.led1 = None
        self.led2 = None
        try:
            self.led1 = LED(18)
            self.led2 = LED(23)
        except (GPIOError, GPIOPinInUse, GPIOPinMissing) as e:
            print(f"Error initializing LEDs: {e}")
            self.cleanup()
            exit(1)

    def both_on(self):
        try:
            self.led1.on()
            self.led2.on()
        except GPIOError as e:
            print(f"Error turning LEDs on: {e}")
            self.cleanup()
            exit(1)

    def both_off(self):
        try:
            self.led1.off()
            self.led2.off()
        except GPIOError as e:
            print(f"Error turning LEDs off: {e}")
            self.cleanup()
            exit(1)

    def toggle(self, cycles=5):
        if cycles == 0:
            return
        try:
            self.both_on()
            time.sleep(1)
            self.both_off()
            time.sleep(1)
