        try:
            self.led1.on()
            self.led2.on()
        except GPIOError as e:
            print(f"Error turning LEDs on: {e}")
            self.cleanup()
            exit(1)

    def both_off(self):
        try:
            self.led1.off()
            self.led2.off()
        except GPIOError as e:
            print(f"Error turning LEDs off: {e}")
            self.cleanup()
            exit(1)

    def toggle(self, cycles=5):
        if cycles == 0:
            return
        try:
            self.both_on()
            time.sleep(1)
            self.both_off()
            time.sleep(1)
            self.toggle(cycles-1)
        except GPIOError as e:
            print(f"Error toggling LEDs: {e}")
            self.cleanup()
            exit(1)

    def cleanup(self):
        if self.led1 is not None:
            self.led1.close()
        if self.led2 is not None:
            self.led2.close()

def sigint_handler(signum, frame):
    led_controller.cleanup()
    exit(1)

led_controller = LEDController()

if led_controller.led1 is not None and led_controller.led2 is not None:
    signal.signal(signal.SIGINT, sigint_handler)
