import pigpio

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pi, pin):
        self.pi = pi
        self.pin = pin
        if not isinstance(pi, pigpio.pi):
            raise MotorError('Invalid or disconnected pigpio.pi instance')
        self.pi.set_mode(pin, pigpio.OUTPUT)
        self.set_frequency(1000)
        self.set_duty_cycle(0)

    def set_frequency(self, freq):
        if not isinstance(freq, int) or freq <= 0:
            raise MotorError('Invalid frequency')
        result = self.pi.set_PWM_frequency(self.pin, freq)
        if result != 0:
            raise MotorError(f'Failed to set PWM frequency, error code: {result}')

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError('Invalid duty cycle, must be an integer in the range 0-255')
        result = self.pi.set_PWM_dutycycle(self.pin, duty)
        if result != 0:
            raise MotorError(f'Failed to set PWM duty cycle, error code: {result}')

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.pi.set_mode(self.pin, pigpio.INPUT)

    def __del__(self):
        self.stop()

