from gpiozero.exc import OutputDeviceBadValue, DeviceClosed, PinInUse, PinInvalid

class RoboticArm:
    def __init__(self):
        self.base = AngularServo(17, min_pulse_width=0.0005, max_pulse_width=0.0025, frequency=50)
        self.shoulder = AngularServo(27, min_pulse_width=0.0005, max_pulse_width=0.0025, frequency=50)
        self.gripper = AngularServo(22, min_pulse_width=0.0005, max_pulse_width=0.0025, frequency=50)
        self.servos = [self.base, self.shoulder, self.gripper]

    def move_joint(self, servo, target_angle):
        target_angle = max(-90, min(90, target_angle))
        try:
            servo.angle = target_angle
            time.sleep(0.4)
        except OutputDeviceBadValue as e:
            print(f"Invalid angle: {target_angle}")
            raise

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        for servo, angle in zip(self.servos, [base_angle, shoulder_angle, gripper_angle]):
            self.move_joint(servo, angle)

    def release(self):
        for servo in self.servos:
            servo.close()

def run_demo_sequence(robot_arm):
    try:
        poses = [(0,0,0), (45,-30,20), (-45,30,-20), (0,0,0)]
        for pose in poses:
            print(f"Moving to pose {pose}")
            robot_arm.go_to_pose(*pose)
    except (DeviceClosed, PinInUse, PinInvalid) as e:
        print(f"Error: {e}")
        robot_arm.release()
    except RuntimeError as e:
        print(f"GPIO allocation error: {e}")
        robot_arm.release()
    finally:
        robot_arm.release()

def cleanup(signum, frame):
    robot_arm.release()
    print("\nExiting...")

robot_arm = RoboticArm()

