import smbus2
import signal
from datetime import datetime

class DS1338:
    I2C_ADDR = 0x68
    I2C_BUS = 1

    def __init__(self):
        self.bus = smbus2.SMBus(self.I2C_BUS)
        self._verify_device()
        signal.signal(signal.SIGINT, self._close_bus)
        signal.signal(signal.SIGTERM, self._close_bus)

    def _verify_device(self):
        try:
            self.bus.read_byte(self.I2C_ADDR)
        except OSError:
            raise IOError(f"No device at address {self.I2C_ADDR}")

    def _close_bus(self, *args):
        self.bus.close()

    @staticmethod
    def _bcd_to_int(bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    @staticmethod
    def _int_to_bcd(n):
        return (n // 10 << 4) | (n % 10)

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.I2C_ADDR, reg)
        except (OSError, smbus2.SMBusTimeout):
            raise IOError(f"Failed to read register {reg}")

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.I2C_ADDR, reg, value)
        except (OSError, smbus2.SMBusTimeout):
            raise IOError(f"Failed to write register {reg}")

    def read_datetime(self, century=21):
        sec = self._read_register(0x00)
        min = self._read_register(0x01)
        hour = self._read_register(0x02) & 0x3F
        day = self._read_register(0x03)
        month = self._read_register(0x04)
        year = self._read_register(0x05)

        return datetime(century*100 + self._bcd_to_int(year),
                        self._bcd_to_int(month),
                        self._bcd_to_int(day),
                        self._bcd_to_int(hour),
                        self._bcd_to_int(min),
                        self._bcd_to_int(sec))

    def write_all(self, sec=None, min=None, hour=None, day=None, month=None, year=None):
        if sec is not None:
            self._write_register(0x00, self._int_to_bcd(sec))
        if min is not None:
            self._write_register(0x01, self._int_to_bcd(min))
        if hour is not None:
            self._write_register(0x02, self._int_to_bcd(hour))
        if day is not None:
            self._write_register(0x03, self._int_to_bcd(day))
        if month is not None:
            self._write_register(0x04, self._int_to_bcd(month))
        if year is not None:
            self._write_register(0x05, self._int_to_bcd(year % 100))

