        min = self._read_register(0x01)
        hour = self._read_register(0x02) & 0x3F
        day = self._read_register(0x03)
        month = self._read_register(0x04)
        year = self._read_register(0x05)

        return datetime(century*100 + self._bcd_to_int(year),
                        self._bcd_to_int(month),
                        self._bcd_to_int(day),
                        self._bcd_to_int(hour),
                        self._bcd_to_int(min),
                        self._bcd_to_int(sec))

    def write_all(self, sec=None, min=None, hour=None, day=None, month=None, year=None):
        if sec is not None:
            self._write_register(0x00, self._int_to_bcd(sec))
        if min is not None:
            self._write_register(0x01, self._int_to_bcd(min))
        if hour is not None:
            self._write_register(0x02, self._int_to_bcd(hour))
        if day is not None:
