import serial
import time
from datetime import datetime
from threading import Thread, Event
from pyserial_led import LED

class FlowRateReader:
    def __init__(self, port='/dev/ttyUSB0', baud=9600, timeout=1):
        self.port = port
        self.baud = baud
        self.timeout = timeout
        self.stop_event = Event()
        self.thread = Thread(target=self.run, daemon=True)
        self.led = LED()

    def start(self):
        self.thread.start()

    def stop(self):
        self.stop_event.set()
        self.thread.join()

    def run(self):
        try:
            with serial.Serial(self.port, self.baud, timeout=self.timeout) as ser:
                while not self.stop_event.is_set():
                    try:
                        line = ser.readline().decode('ascii', 'replace').strip()
                        flow_rate = float(line)
                        timestamp = datetime.now().isoformat()
                        log_entry = f'{timestamp} - Flow Rate: {flow_rate} L/min'
                        print(log_entry)
                        with open('water_flow_log.txt', 'a') as f:
                            f.write(log_entry + '\n')
                        time.sleep(1)
                    except ValueError:
                        print(f'Warning: Non-numeric flow rate data: {line}')
                    except serial.SerialException as e:
                        print(f'Error: {e}')
                        self.stop()
        except Exception as e:
            print(f'Error: {e}')
            self.stop()

if __name__ == '__main__':
    reader = FlowRateReader()
    reader.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        reader.stop()

