    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            self.gps = GPS(self.ser)
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {str(e)}")
            return False
        return True

    def disconnect(self):
        if self.ser is not None:
            try:
                self.ser.close()
            except Exception as e:
                logging.error(f"Failed to close serial port: {str(e)}")

    def read_gps_data(self):
        while True:
            try:
                line = self.ser.readline().decode("utf-8").strip()
                if not line.startswith("$GPGGA"):
                    continue
                fields = line.split(",")
                if len(fields) != 15 or not fields[1] or not fields[3] or not fields[8]:
                    logging.warning(f"Invalid GPGGA sentence: {line}")
                    continue
                try:
                    latitude = abs(float(fields[2][:2])) + float(fields[2][2:]) / 60
                    if fields[1][1] == "S":
                        latitude = -latitude
                    longitude = abs(float(fields[4][:3])) + float(fields[4][3:]) / 60
                    if fields[1][1] == "W":
                        longitude = -longitude
                    altitude = float(fields[9])
                    satellite_count = int(fields[12])
                except ValueError:
                    logging.warning(f"Failed to parse GPGGA sentence: {line}")
                    continue
                return GPS_readings(latitude, longitude, altitude, satellite_count)
            except serial.SerialException as e:
                logging.error(f"Serial port error: {str(e)}")
                return None
            except serial.SerialTimeoutException:
                logging.warning("Serial read timeout")
                return None

