import signal
from serial import SerialException

class ESP8266:
    def __init__(self, port='/dev/ttyAMA0', baud=115200):
        self.port = port
        self.baud = baud
        self.ser = None
        try:
            self.ser = serial.Serial(port=self.port, baudrate=self.baud, timeout=5, write_timeout=5)
            signal.signal(signal.SIGINT, self._close)
        except SerialException as e:
            print(f"Error opening serial port {self.port}: {str(e)}")
            exit(1)

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.ser.write(command.encode('utf-8') + b'\r\n')
            time.sleep(delay)
            response = self._read_response()
            if response is not None:
                return response
        return None

    def _read_response(self):
        response = ''
        start_time = time.time()
        while time.time() - start_time < 5:
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting).decode('utf-8')
                if 'OK' in response or 'ERROR' in response or 'FAIL' in response:
                    return response
        return None

    def test_connection(self):
        return 'OK' in self._send_command('AT')

    def restart(self):
        return 'OK' in self._send_command('AT+RST', delay=2)

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"'
        return 'WIFI GOT IP' in self._send_command(command, delay=5)

    def _close(self, signum, frame):
        if self.ser is not None:
            self.ser.close()
        exit(0)

