from contextlib import contextmanager

class RaspberryPi:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        try:
            self.ser = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise SystemExit(f"Error opening serial port {port}: {str(e)}")

    def __enter__(self):
        return self

    def __exit__(self, type, value, traceback):
        self.close()

    def signal_handler(self, signal, frame):
        print('\nShutting down safely...')
        self.close()
        exit(0)

    def close(self):
        if self.ser and self.ser.is_open:
            self.ser.close()

    def attach(self):
        try:
            self.ser.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            return self.ser.write(b'AT+CGNSPWR?\r\n') == 7
        except serial.SerialException as e:
            print(f"Error writing to serial port: {str(e)}")
            return False

    def detach(self):
        try:
            self.ser.write(b'AT+CGNSPWR=0\r\n')
            return self.ser.write(b'AT+CGNSPWR?\r\n') == 7
        except serial.SerialException as e:
            print(f"Error writing to serial port: {str(e)}")
            return False

    def get_data(self):
        try:
            data = self.ser.readline().decode().strip()
            if data.startswith('$GPRMC') and data.split(',')[2] == 'A':
                return data.split(',')
            else:
                return None
        except serial.SerialException as e:
            print(f"Error reading from serial port: {str(e)}")
            return None


