from paho.mqtt import client as mqtt_client

class SimpleGPS:
    def __init__(self):
        self.ser = None
        self.led = LED(21)
        self.picamera2 = Picamera2()
        self.mqtt_client = mqtt_client.Client()

    def connect(self):
        try:
            self.ser = serial.Serial('/dev/serial0', 9600)
            return True
        except (serial.SerialException, OSError) as e:
            logging.error(f"Failed to connect to GPS: {e}")
            return False

    def read_data(self):
        try:
            if self.ser.in_waiting > 0:
                data = self.ser.readline().decode("utf-8", "ignore").strip()
                return data
        except (serial.SerialException, OSError) as e:
            logging.error(f"Failed to read data from GPS: {e}")
        return None

    def parse_gga(self, sentence):
        try:
            fields = sentence.split(',')
            if fields[0] not in ("$GPGGA", "$GNGGA"):
                return None
            utc_time = fields[1]
            latitude = fields[2]
            if latitude:
                latitude = float(latitude[:2]) + float(latitude[2:]) / 60
                if fields[3] == 'S':
                    latitude = -latitude
            else:
                latitude = None
            longitude = fields[4]
            if longitude:
                longitude = float(longitude[:3]) + float(longitude[3:]) / 60
                if fields[5] == 'W':
                    longitude = -longitude
            else:
                longitude = None
            fix_quality = fields[6]
            num_satellites = fields[7]
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites,
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Failed to parse GGA sentence: {e}")
            return None

    def close(self):
        try:
            if self.ser and self.ser.is_open:
                self.ser.close()
        except (serial.SerialException, OSError) as e:
            logging.error(f"Failed to close GPS connection: {e}")
